package com.pratik.imagetap;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;
/** Short, replayable guides. Reading help never enables or starts automation. */
final class HelpGuide {
 static final String[] TITLES={"Getting started","Picture actions","Screen regions","Settings","Timeline","Auto Tap","Crop a picture","Presets & sharing","Recognition","Gestures","Detection rules","Appearance","Session & permissions","Speed & run limits","Number of targets","Saved layouts","Repeat markers"};
 static final String[][] STEPS={
 {"Start at Home. First enable Android access. Keep Allow actions OFF while learning. Choose Auto Tap for a fixed place, Actions for a picture, or Timeline for ordered steps.","Enable Android access from Settings → Session & permissions → Accessibility settings. Choose AutoBash and turn its service on. This lets AutoBash send touches; you can turn it off there later.","Allow actions is the master switch. Off means preview only. Start with the Auto Tap test pad before using another app.","Pause keeps your place. Stop ends the run. The floating brain's × is Stop in simple mode. Move the popup away from places you want to tap."},
 {"Choose Tap, a swipe direction, Back or Home. The saved picture will trigger that action when it appears.","Add a screenshot and keep only the button or symbol you need. A target means one saved picture. Tap its tile to edit; drag tiles to reorder.","Choose a preset to keep separate groups for different apps. Activate the pictures you want to use.","Return Home, choose Image recognition, then Start session. With Allow actions off, check the highlights first. Enable it only when the right object is found."},
 {"Regions are parts of the screen. They apply to all saved pictures, not just one.","Open Screen regions. Draw a box where you want a special rule.","Choose accuracy for stricter or looser matching, or exclude the box to ignore it. Save the area.","Turn Screen regions on in Settings → Detection rules. Excluded areas will not trigger image actions."},
 {"Open one folded section at a time. Keep the defaults until you know what you want to change.","Recognition controls picture matching. Gestures controls touches and swipes. Appearance controls the popup and effects.","Every setting has a short explanation underneath. Tap a section's help button for an example.","If no action happens, check Allow actions, Accessibility access, Pause, and whether the popup covers the target."},
 {"A timeline is a list of actions played in order, like a recipe.","Add a step, choose its action and place its tap or swipe markers. Set the wait before that step.","For example: wait 3.4 seconds, tap; then wait 1.2 seconds, swipe down. These are waits between steps, not clock times.","Review the order and repetition options, enable Allow actions, then start. Pause holds your place; Stop ends the sequence."},
 {"Choose Number of targets. Each number is one place to tap. Start with one.","Open Auto Tap controls. Drag the numbered circle to the place you want. Tap the circle for exact position or its own speed.","Choose Speed. Hold is how long the finger stays down; gap is the wait after a tap. Start with Reliable.","Press Play. The numbers disappear so taps can reach the app. Targets run 1, 2, 3…; one trip through them is a cycle. Pause brings the markers back.","Try Test taps on this phone first. Put the marker inside the green pad and the menu outside it. Play, then Pause, to see received taps."},
 {"Pinch to zoom and move the picture until the symbol is easy to see.","Crop around the symbol. Leave out changing backgrounds. Use the mask tools to erase unwanted pixels; transparent parts are ignored.","Undo fixes the last edit. Check the action destination before saving.","Save the target, return to your app and preview a match. For tiny symbols, use an original screenshot rather than a resized picture."},
 {"A preset is a named box of saved targets. Use different boxes for different apps.","Save the current set to a named slot before loading another. Loading changes the active set.","Home → Back up or restore everything saves every action, all preset slots, regions, timelines, Auto Tap layouts and settings in one file. Restore replaces the whole setup and leaves actions OFF. Import preset still accepts older single-preset files.","Merge duplicates finds similar pictures. Review the proposed group before merging; lowering the threshold can group different buttons."},
 {"Scan pulse means the wait between attempts to look at the screen. A smaller number asks for more frequent scans; processing can take longer.","Image similarity is how closely a picture must match. Higher is stricter. 100% expects exact retained pixels and often misses moving backgrounds.","Try a tight crop before lowering similarity. Use two-frame confirmation to reduce wrong clicks.","Fast performance uses more processing power. Alternate sizes can find resized icons but takes longer."},
 {"Touch duration is how long the finger stays down. If an app ignores a tap, try a longer duration.","Action delay adds a wait between actions. Swipe duration controls how long the swipe takes.","Swipe distance is a portion of the screen. Choose the screen centre if the detected picture should only trigger the swipe.","Back and Home are Android navigation actions. Home leaves the current app."},
 {"Two-frame confirmation checks the same target twice before acting. It can reduce mistakes but adds a wait.","Repeat visible targets allows another action while the same picture remains on screen.","Screen regions enables the areas you drew. An excluded region never triggers an image action.","If a valid picture is missed, check exclusions and the popup position before changing accuracy."},
 {"Detailed launcher shows status, Save, Pause and Stop. Simple mode shows a small brain with × to stop.","Simple and advanced popup size are saved separately. Return to the session to apply a size change.","Focus guides show where matching is happening. Action effects show dispatched actions, not proof that another app accepted them.","Reduce motion turns off ambient animation. You can keep it on without changing recognition."},
 {"Accessibility access lets AutoBash place controls and perform actions. Enable it in Android's settings only when you want to use the app.","Launch app chooses where to go when a session starts. None selected returns you to Home.","Android can stop background work or block protected screenshots. Reopen AutoBash if its service is unavailable.","After recovery, review the screen before resuming. Stop ends the session; do not uninstall to update or your saved data may be lost."},
 {"Hold is the time a finger stays down. Gap is the wait after it lifts. Times here are milliseconds: 1000 ms = 1 second.","Reliable is a good starting point. Fastest uses the minimum hold, but some apps will miss those short touches.","Start delay gives you time before the first tap. Cycle limit stops after visiting all targets that many times; 0 keeps repeating.","Saving speed starts a new run. Individual target overrides can use a different hold or gap."},
 {"Choose how many places to tap, from 1 to 20.","Apply, then drag each numbered circle while paused.","Reducing the number removes the last targets. Changing the count starts a new run."},
 {"Save your current target positions and timing to one of three named slots.","Load a slot to use its saved layout. Loading starts a new run.","Keep separate layouts for different apps. Check positions after rotating the screen."}
 ,{"Repeat markers runs an action on a timer without looking for a picture.","Open Actions, choose an action, then its general timed controls. Place tap or swipe markers and choose an interval.","Return Home → Session controls and choose General · repeat markers before starting.","Use Auto Tap for a simple repeated tap. Use Timeline when actions need a particular order. Pause keeps your place; Stop ends the run."}
 };
 static int topic(String title){if(title.startsWith("Target "))return 5;if(title.equals("Name this layout"))return 15;for(int i=0;i<TITLES.length;i++)if(TITLES[i].equals(title))return i;return 3;}
 static void show(Context c,int topic){showStep(c,Math.max(0,Math.min(topic,TITLES.length-1)),0);}
 static void showStep(Context c,int topic,int index){LinearLayout box=Ui.column(c);box.setPadding(Ui.dp(c,24),Ui.dp(c,16),Ui.dp(c,24),Ui.dp(c,16));TextView count=Ui.label(c,"STEP "+(index+1)+" OF "+STEPS[topic].length,12,Ui.GREEN);box.addView(count);ProgressBar progress=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(STEPS[topic].length);progress.setProgress(index+1);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(Ui.GREEN));box.addView(progress,new LinearLayout.LayoutParams(-1,Ui.dp(c,8)));TextView text=Ui.label(c,STEPS[topic][index],18,Ui.CREAM);text.setPadding(0,Ui.dp(c,16),0,Ui.dp(c,8));box.addView(text);ScrollView scroll=new ScrollView(c);scroll.addView(box);AlertDialog d=new AlertDialog.Builder(c).setTitle(TITLES[topic]).setView(scroll).setNegativeButton("Close",null).setNeutralButton(index>0?"Back":"All guides",(v,w)->{if(index>0)showStep(c,topic,index-1);else index(c);}).setPositiveButton(index+1<STEPS[topic].length?"Next":c instanceof MainActivity?(topic==0?"Try practice":"Open this section"):"Done",(v,w)->{if(index+1<STEPS[topic].length)showStep(c,topic,index+1);else if(c instanceof MainActivity){if(topic==0)AutoTapUi.launch((Activity)c,true);else ((MainActivity)c).openGuideDestination(topic);}}).create();if(!(c instanceof Activity))d.getWindow().setType(WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY);d.show();Ui.sheet(d);if(c instanceof TapService)((TapService)c).autoTapDialog(d);}
 static void index(Context c){AlertDialog dialog=new AlertDialog.Builder(c).setTitle("What do you need help with?").setItems(TITLES,(d,i)->show(c,i)).setNegativeButton("Close",null).create();if(!(c instanceof Activity))dialog.getWindow().setType(WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY);dialog.show();Ui.sheet(dialog);if(c instanceof TapService)((TapService)c).autoTapDialog(dialog);}
 static void button(Context c,LinearLayout parent,int topic){Button b=Ui.button(c,"How to use this · ?",false);parent.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->show(c,topic));}
}
